package com.nequard.community;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="community_nodes") public class CommunityNode{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)String name;String nodeType="HOTSPOT",status="ONLINE",upstreamType="FIBER";Double capacityMbps,latitude,longitude;public UUID getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getNodeType(){return nodeType;}public void setNodeType(String v){nodeType=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getUpstreamType(){return upstreamType;}public void setUpstreamType(String v){upstreamType=v;}public Double getCapacityMbps(){return capacityMbps;}public void setCapacityMbps(Double v){capacityMbps=v;}public Double getLatitude(){return latitude;}public void setLatitude(Double v){latitude=v;}public Double getLongitude(){return longitude;}public void setLongitude(Double v){longitude=v;}}
